//refAssemblies: System.Diagnostics.Process.dll, System.Net.Http.dll, TCAdmin.Monitor.SDK.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Text.RegularExpressions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Wine (Linux host) only: installs what the panel needs to run this Windows server - wine, winetricks, Xvfb and
// xdotool - with apt (Debian/Ubuntu) or dnf/yum (Red Hat), then prepares the service's own Wine prefix: Wine Mono (the
// .NET Framework runtime the server runs on) and the Visual C++ runtime. Idempotent:
// anything already present is skipped. Runs before the create/reinstall (host packages, so the panel's Wine check
// passes) and after it (the prefix, once the service user and files exist).
if (!System.OperatingSystem.IsLinux()) return;

// Windows runtimes (winetricks verbs) the server needs inside the prefix: it refuses to start without the Visual C++
// 2015-2022 runtime ("Please install latest C++ redistributable package").
var verbs = new[] { "vcrun2022" };

var tools = new (string Command, string[] Apt, string[] Rpm)[]
{
    ("wine", new[] { "wine", "wine64" }, new[] { "wine" }),
    ("wineserver", new[] { "wine", "wine64" }, new[] { "wine" }),
    ("winetricks", new[] { "winetricks" }, new[] { "winetricks" }),
    ("cabextract", new[] { "cabextract" }, new[] { "cabextract" }),
    ("Xvfb", new[] { "xvfb" }, new[] { "xorg-x11-server-Xvfb", "xorg-x11-server-Xvfb.x86_64" }),
    ("xdotool", new[] { "xdotool" }, new[] { "xdotool" }),
};
var apt = Shell("command -v apt-get", out _);
var installer = apt ? "DEBIAN_FRONTEND=noninteractive apt-get install -y " : Shell("command -v dnf", out _) ? "dnf install -y " : "yum install -y ";
var updated = false;
foreach (var tool in tools)
{
    if (Shell("command -v " + tool.Command, out _)) continue;
    var names = apt ? tool.Apt : tool.Rpm;
    ScriptConsole.WriteLine((object)(tool.Command + " is missing on this host; installing " + string.Join(" or ", names) + "."));
    var installed = names.Any(p => Shell(installer + p, out _));
    if (!installed && apt && !updated)
    {
        updated = Shell("DEBIAN_FRONTEND=noninteractive apt-get update", out _);
        installed = names.Any(p => Shell(installer + p, out _));
    }
    if (!installed || !Shell("command -v " + tool.Command, out _))
        throw new Exception(tool.Command + " is missing and could not be installed. Install one of these packages on the host: " + string.Join(", ", names));
}
Shell("wine --version", out var wineVersion);
ScriptConsole.WriteLine((object)("Wine on this host: " + wineVersion.Trim()));

var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/');
// Before the create/reinstall the service files and its run-as configuration do not exist yet.
string user = null;
if (File.Exists(Path.Combine(root, "DedicatedServer64", "SpaceEngineersDedicated.exe")))
{
    try { user = ServiceManagerService.GetServiceCredential(ThisService.ServiceId)?.UserName; }
    catch (FileNotFoundException) { }
}
if (string.IsNullOrEmpty(user) || !Shell("id -u '" + user + "'", out _))
{
    ScriptConsole.WriteLine((object)"The service is not created yet; the Wine prefix is prepared after the files are installed.");
    return;
}
var prefix = Path.Combine(root, ".wine");
// Every Wine call as the service user with the environment the panel starts the server with (root would leave
// root-owned files in the prefix).
var wineEnv = "runuser -u '" + user + "' -- env WINEPREFIX='" + prefix + "' HOME='" + root
              + "' WINEARCH=win64 WINEDEBUG=-all WINEDLLOVERRIDES='mscoree=;mshtml=' ";

// The first start creates the Wine prefix (about a minute), longer than the panel waits for the start that follows
// the create. Create it here; the panel skips it when its marker file is present.
var marker = Path.Combine(prefix, ".tcadmin-initialized");
if (!File.Exists(marker))
{
    ScriptConsole.WriteLine((object)"Creating the Wine prefix (about a minute).");
    if (!Shell(wineEnv + "wineboot -u", out var bootOutput))
        throw new Exception("wineboot failed: " + string.Join("\n", bootOutput.Split('\n').TakeLast(15)));
    Shell(wineEnv + "wineserver -w", out _);
    Shell("runuser -u '" + user + "' -- sh -c \"date -u +%Y-%m-%dT%H:%M:%SZ > '" + marker + "'\"", out _);
    ScriptConsole.WriteLine((object)"The Wine prefix is ready.");
}

// Wine Mono: the server is a .NET Framework 4.8 program. Wine's mscoree runs it on Wine Mono; install the version this
// Wine build asks for (its appwiz.cpl names it) into the prefix.
var monoMarker = Path.Combine(prefix, ".tcadmin-wine-mono");
if (!File.Exists(monoMarker))
{
    var monoVersion = WineMonoVersion();
    if (monoVersion == null) throw new Exception("Could not find the Wine Mono version this Wine build needs.");
    var msi = Path.Combine(root, ".tca", "wine-mono-" + monoVersion + "-x86.msi");
    if (!File.Exists(msi))
    {
        ScriptConsole.WriteLine((object)("Downloading Wine Mono " + monoVersion + "."));
        Directory.CreateDirectory(Path.GetDirectoryName(msi));
        using (var http = new HttpClient { Timeout = TimeSpan.FromMinutes(10) })
            File.WriteAllBytes(msi, await http.GetByteArrayAsync("https://dl.winehq.org/wine/wine-mono/" + monoVersion + "/wine-mono-" + monoVersion + "-x86.msi", ThisCancellationToken));
        Shell("chown '" + user + "' '" + msi + "'", out _);
    }
    ScriptConsole.WriteLine((object)("Installing Wine Mono " + monoVersion + " into the Wine prefix."));
    if (!Shell(wineEnv + "wine msiexec /i '" + msi + "' /qn", out var monoOutput))
        throw new Exception("Wine Mono did not install: " + string.Join("\n", monoOutput.Split('\n').TakeLast(15)));
    Shell(wineEnv + "wineserver -w", out _);
    Shell("runuser -u '" + user + "' -- sh -c \"echo " + monoVersion + " > '" + monoMarker + "'\"", out _);
    File.Delete(msi);
}

// winetricks records every verb it installed in the prefix.
var log = Path.Combine(prefix, "winetricks.log");
var done = File.Exists(log) ? File.ReadAllLines(log).Select(l => l.Trim()).ToHashSet() : new HashSet<string>();
var todo = verbs.Where(v => !done.Contains(v)).ToList();
if (todo.Count > 0)
{
    ScriptConsole.WriteLine((object)("Installing " + string.Join(", ", todo) + " into the Wine prefix (a few minutes)."));
    // Installers open windows: give them a virtual display.
    var display = Shell("command -v xvfb-run", out _) ? "xvfb-run -a " : "";
    if (!Shell(wineEnv + display + "winetricks -q " + string.Join(" ", todo), out var output))
        throw new Exception("winetricks failed: " + string.Join("\n", output.Split('\n').TakeLast(15)));
    ScriptConsole.WriteLine((object)"Windows runtimes installed.");
}
Shell(wineEnv + "wineserver -w", out _);

// The version string in Wine's appwiz.cpl (addons.c: "wine-mono-%s-x86.msi" next to the version it was built for).
string WineMonoVersion()
{
    Shell("dirname \"$(readlink -f \"$(command -v wine)\")\"", out var binDir);
    var candidates = new List<string>();
    foreach (var baseDir in new[] { Path.Combine(binDir.Trim(), ".."), "/usr/lib/wine", "/usr/lib64/wine", "/usr/lib/x86_64-linux-gnu/wine", "/opt/wine-stable/lib/wine", "/opt/wine-staging/lib/wine", "/opt/wine-devel/lib/wine" })
    {
        if (!Directory.Exists(baseDir)) continue;
        try { candidates.AddRange(Directory.GetFiles(baseDir, "appwiz.cpl", SearchOption.AllDirectories)); } catch { }
    }
    // Every "x.y.z" string of the file (ASCII or UTF-16); the Gecko version (2.x) is the only other one.
    var versions = new HashSet<string>();
    foreach (var file in candidates.Distinct())
    {
        var bytes = File.ReadAllBytes(file);
        foreach (var source in new[] { System.Text.Encoding.Latin1.GetString(bytes), System.Text.Encoding.Unicode.GetString(bytes), System.Text.Encoding.Unicode.GetString(bytes, 1, bytes.Length - 1) })
            foreach (Match match in Regex.Matches(source, "(?<=\0)([0-9]{1,2}\\.[0-9]{1,2}\\.[0-9]{1,2})(?=\0)"))
                versions.Add(match.Groups[1].Value);
    }
    var ordered = versions.Where(v => int.Parse(v.Split('.')[0]) >= 4).OrderByDescending(v => Version.Parse(v)).ToList();
    using (var http = new HttpClient { Timeout = TimeSpan.FromSeconds(30) })
    {
        foreach (var version in ordered)
        {
            var request = new HttpRequestMessage(HttpMethod.Head, "https://dl.winehq.org/wine/wine-mono/" + version + "/wine-mono-" + version + "-x86.msi");
            try { if (http.Send(request).IsSuccessStatusCode) return version; } catch { }
        }
    }
    ScriptConsole.WriteLine((object)("Version strings found in appwiz.cpl (" + string.Join(", ", candidates.Distinct()) + "): " + string.Join(", ", versions)));
    return null;
}

bool Shell(string cmd, out string text)
{
    using (var process = Process.Start(new ProcessStartInfo("/bin/sh", new[] { "-c", cmd }) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        var stderr = process.StandardError.ReadToEndAsync();
        text = process.StandardOutput.ReadToEnd() + stderr.Result;
        process.WaitForExit();
        return process.ExitCode == 0;
    }
}

//refAssemblies: System.Diagnostics.Process.dll, System.Security.Cryptography.dll, System.Xml.ReaderWriter.dll, System.Private.Xml.Linq.dll, System.Xml.XDocument.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Xml;
using System.Xml.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

var root = (string)ThisService.RootDirectory;
var instance = Path.Combine(root, "Instance");

// 1. Space Engineers' physics engine (Havok.dll) needs the Visual C++ 2013 runtime, its other native libraries the
//    2015-2022 one. The server ships both installers in _CommonRedist; install whichever is missing (once per host).
if (System.OperatingSystem.IsWindows())
{
    var system32 = Environment.SystemDirectory;
    var redists = new[]
    {
        new { Name = "Visual C++ 2013 (x64)", Files = new[] { "msvcr120.dll", "msvcp120.dll" }, Installer = Path.Combine("_CommonRedist", "vcredist", "2013", "vcredist_x64.exe") },
        new { Name = "Visual C++ 2015-2022 (x64)", Files = new[] { "vcruntime140.dll", "vcruntime140_1.dll", "msvcp140.dll" }, Installer = Path.Combine("_CommonRedist", "vcredist", "2019", "VC_redist.x64.exe") },
    };
    foreach (var redist in redists)
    {
        if (redist.Files.All(f => File.Exists(Path.Combine(system32, f)))) continue;
        var installer = Path.Combine(root, redist.Installer);
        if (!File.Exists(installer))
        {
            ScriptConsole.WriteLine((object)("The " + redist.Name + " runtime is missing and its installer (" + redist.Installer + ") was not found. Reinstall the service, or install the runtime on this host."));
            continue;
        }
        ScriptConsole.WriteLine((object)("Installing the " + redist.Name + " runtime..."));
        var psi = new ProcessStartInfo(installer, new[] { "/install", "/quiet", "/norestart" }) { UseShellExecute = false, CreateNoWindow = true };
        using (var process = Process.Start(psi))
        {
            await process.WaitForExitAsync(ThisCancellationToken);
            // 0 = installed, 1638 = a newer version is already there, 3010 = installed, a reboot is pending.
            if (process.ExitCode == 0 || process.ExitCode == 1638 || process.ExitCode == 3010)
                ScriptConsole.WriteLine((object)("Installed the " + redist.Name + " runtime."));
            else
                throw new Exception("The " + redist.Name + " runtime installer failed with exit code " + process.ExitCode + ".");
        }
    }
}

// 2. The instance folder (-path): configuration, worlds, logs and the mods the server downloads. The server exits at
//    once when it does not exist.
Directory.CreateDirectory(instance);

// Torch saves Torch.cfg when it starts; the panel writes its config files with an ACL of their own on Windows (no write
// access for the service account). Reset the file to the service folder's inherited permissions.
var torchConfig = Path.Combine(root, "Torch.cfg");
if (System.OperatingSystem.IsWindows() && File.Exists(torchConfig) && Safe(torchConfig, root))
{
    using (var icacls = Process.Start(new ProcessStartInfo("icacls.exe", new[] { torchConfig, "/reset", "/Q" }) { UseShellExecute = false, RedirectStandardOutput = true, RedirectStandardError = true, CreateNoWindow = true }))
        await icacls.WaitForExitAsync(ThisCancellationToken);
}

// 3. The configuration. The panel's editor writes the plain password and the administrator list into elements of
//    its own (the server ignores unknown elements); the server gets the salted hash and the Administrators list.
var cfgPath = Path.Combine(instance, "SpaceEngineers-Dedicated.cfg");
if (!Safe(cfgPath, instance))
    throw new Exception("Instance/SpaceEngineers-Dedicated.cfg (or the Instance folder) is a symbolic link: replace it with a regular file.");
if (!File.Exists(cfgPath))
{
    ScriptConsole.WriteLine((object)"SpaceEngineers-Dedicated.cfg is missing; the server starts with its defaults.");
    return;
}
var cfgDoc = XDocument.Load(cfgPath);
var cfg = cfgDoc.Root;
var changed = new List<string>();

XElement Child(XElement parent, string name, bool create = true)
{
    var element = parent.Elements().FirstOrDefault(e => e.Name.LocalName == name);
    if (element == null && create) { element = new XElement(name); parent.Add(element); }
    return element;
}
void Set(XElement parent, string name, string value)
{
    var element = Child(parent, name);
    if (element.HasElements || element.Value != value) { element.RemoveNodes(); element.Value = value; changed.Add(name); }
}

// The service owns the address, the ports and the player limit (also passed on the command line).
Set(cfg, "IP", Convert.ToString(ThisService.IPAddress));
Set(cfg, "ServerPort", Convert.ToString(ThisService.GamePort));
try { Set(cfg, "SteamPort", Convert.ToString(ThisService.Ports["SteamPort"])); } catch { } // a service created before the port existed
var session = Child(cfg, "SessionSettings");
Set(session, "MaxPlayers", Convert.ToString(ThisService.Slots));

// The server rewrites the whole file (and drops the panel's elements) the first time it needs a DedicatedId.
var dedicatedId = Child(cfg, "DedicatedId");
if (!long.TryParse(dedicatedId.Value, out var id) || id == 0)
{
    var bytes = RandomNumberGenerator.GetBytes(8);
    bytes[7] &= 0x7f;
    Set(cfg, "DedicatedId", Math.Max(1, BitConverter.ToInt64(bytes, 0)).ToString());
}

// Password: PBKDF2-SHA1 (10000 iterations, 20 bytes) over the base64 salt, exactly like the game's own SetPassword.
var password = Child(cfg, "ServerPassword", false)?.Value ?? "";
var saltElement = Child(cfg, "ServerPasswordSalt");
byte[] salt;
try { salt = Convert.FromBase64String(saltElement.Value); } catch { salt = new byte[0]; }
if (salt.Length == 0)
{
    salt = RandomNumberGenerator.GetBytes(16);
    Set(cfg, "ServerPasswordSalt", Convert.ToBase64String(salt));
}
var hash = "";
if (password.Length > 0)
{
    using (var kdf = new Rfc2898DeriveBytes(password, salt, 10000, HashAlgorithmName.SHA1))
        hash = Convert.ToBase64String(kdf.GetBytes(20));
}
Set(cfg, "ServerPasswordHash", hash);

// Administrators: SteamID64s from the panel's comma-separated list.
var adminList = Child(cfg, "AdminSteamIds", false);
if (adminList != null)
{
    var ids = Regex.Matches(adminList.Value, "[0-9]{17}").Select(m => m.Value).Distinct().ToList();
    var admins = Child(cfg, "Administrators");
    var current = admins.Elements().Select(e => e.Value.Trim()).ToList();
    if (!current.SequenceEqual(ids))
    {
        admins.RemoveNodes();
        foreach (var steamId in ids) admins.Add(new XElement("string", steamId));
        changed.Add("Administrators");
    }
}

if (changed.Count > 0)
{
    Save(cfgDoc, cfgPath);
    ScriptConsole.WriteLine((object)("Updated SpaceEngineers-Dedicated.cfg: " + string.Join(", ", changed.Distinct()) + "."));
}

// 4. The gameplay settings of the editor are the settings of a new world; an existing world keeps its own copy in
//    Sandbox_config.sbc. Copy the panel-managed settings into the world the server loads, so an edit applies to it.
var saves = Path.Combine(instance, "Saves");
string world = null;
var outside = new List<string>();
var lastSession = Path.Combine(saves, "LastSession.sbl");
if (File.Exists(lastSession) && Safe(lastSession, saves))
{
    var last = XDocument.Load(lastSession);
    var pathElement = last.Root.Elements().FirstOrDefault(e => e.Name.LocalName == "Path");
    var recorded = pathElement?.Value ?? "";
    if (recorded.Length > 0)
    {
        var local = LocalPath(recorded);
        var candidate = Path.IsPathRooted(local) ? local : Path.Combine(saves, local);
        if (!Directory.Exists(candidate) || !Safe(candidate, saves))
        {
            // The service was moved or copied (the path is another service's folder, which may still exist): the same
            // world folder in this service's Saves.
            var moved = Path.Combine(saves, recorded.TrimEnd('\\', '/').Split('\\', '/').Last());
            if (Directory.Exists(moved) && Safe(moved, saves))
            {
                pathElement.Value = System.OperatingSystem.IsWindows() ? moved : "Z:" + moved.Replace('/', '\\');
                Save(last, lastSession);
                ScriptConsole.WriteLine((object)("LastSession.sbl now points to " + moved + "."));
                candidate = moved;
            }
        }
        if (Directory.Exists(candidate) && Safe(candidate, saves)) world = candidate;
        else if (Directory.Exists(candidate)) outside.Add("LastSession.sbl");
    }
}
if (world == null)
{
    var loadWorld = Child(cfg, "LoadWorld", false)?.Value ?? "";
    if (loadWorld.Length > 0)
    {
        var localWorld = LocalPath(loadWorld);
        var candidate = Path.IsPathRooted(localWorld) ? localWorld : Path.Combine(saves, localWorld);
        if (Path.HasExtension(candidate) && File.Exists(candidate)) candidate = Path.GetDirectoryName(candidate);
        if (Directory.Exists(candidate) && !Safe(candidate, saves)) outside.Add("LoadWorld");
        else if (Directory.Exists(candidate)) world = candidate;
    }
}
if (outside.Count > 0)
    ScriptConsole.WriteLine((object)("Ignored the world path of " + string.Join(" and ", outside) + ": a world must be a folder in Instance/Saves (no symbolic links)."));
var worldConfig = world == null ? null : Path.Combine(world, "Sandbox_config.sbc");
if (worldConfig == null || !File.Exists(worldConfig) || !Safe(worldConfig, saves))
{
    ScriptConsole.WriteLine((object)"No world yet: the server creates one from the configuration.");
    return;
}
var worldDoc = XDocument.Load(worldConfig);
var settings = Child(worldDoc.Root, "Settings");
var applied = new List<string>();
foreach (var name in "MaxPlayers,GameMode,EnvironmentHostility,InventorySizeMultiplier,AssemblerSpeedMultiplier,AssemblerEfficiencyMultiplier,RefinerySpeedMultiplier,AutoSaveInMinutes,ViewDistance,TotalPCU,BlockLimitsEnabled,MaxFloatingObjects,MaxBackupSaves,EnableSpectator,EnableCopyPaste,WeaponsEnabled,ThrusterDamage,CargoShipsEnabled,EnableEncounters,EnableDrones,EnableWolfs,EnableSpiders,EnableIngameScripts,EnableOxygen,EnableOxygenPressurization,Enable3rdPersonView,EnableSunRotation,EnableJetpack,SpawnWithTools,EnableRespawnShips,PermanentDeath,EnableEconomy,WeatherSystem,EnableVoxelDestruction,TrashRemovalEnabled,ExperimentalMode".Split(','))
{
    var source = Child(session, name, false);
    if (source == null || source.HasElements) continue;
    var target = Child(settings, name);
    if (target.HasElements || target.Value != source.Value) { target.RemoveNodes(); target.Value = source.Value; applied.Add(name); }
}
// Workshop mods installed in the panel (Instance/WorkshopMods.txt, "<id><TAB><title>") that the world does not list yet,
// e.g. a mod installed before the world existed. Mods added to the world by hand are left alone.
var modList = Path.Combine(instance, "WorkshopMods.txt");
var addedMods = new List<string>();
if (File.Exists(modList) && Safe(modList, instance))
{
    var mods = Child(worldDoc.Root, "Mods");
    foreach (var line in File.ReadAllLines(modList))
    {
        var parts = line.Split('\t');
        var modId = parts[0].Trim();
        if (!Regex.IsMatch(modId, "^[0-9]+$") || mods.Elements().Any(m => (string)m.Element("PublishedFileId") == modId)) continue;
        var title = parts.Length > 1 && parts[1].Trim().Length > 0 ? parts[1].Trim() : modId;
        mods.Add(new XElement("ModItem", new XAttribute("FriendlyName", title),
            new XElement("Name", modId + ".sbm"), new XElement("PublishedFileId", modId), new XElement("PublishedServiceName", "Steam")));
        addedMods.Add(title);
    }
}
// Workshop mods uninstalled in the panel while the server was running (it wrote them back when it saved).
var removedList = Path.Combine(instance, "WorkshopMods.removed.txt");
var removedMods = new List<string>();
var removedListSafe = Safe(removedList, instance);
if (File.Exists(removedList) && removedListSafe)
{
    var mods = Child(worldDoc.Root, "Mods");
    foreach (var modId in File.ReadAllLines(removedList).Select(l => l.Trim()).Where(l => l.Length > 0))
    {
        var items = mods.Elements().Where(m => (string)m.Element("PublishedFileId") == modId).ToList();
        if (items.Count == 0) continue;
        items.ForEach(i => i.Remove());
        removedMods.Add(modId);
    }
}
if (applied.Count > 0 || addedMods.Count > 0 || removedMods.Count > 0)
{
    Save(worldDoc, worldConfig);
    if (applied.Count > 0) ScriptConsole.WriteLine((object)("Applied to the world " + Path.GetFileName(world) + ": " + string.Join(", ", applied) + "."));
    if (addedMods.Count > 0) ScriptConsole.WriteLine((object)("Added the Workshop mods to the world " + Path.GetFileName(world) + ": " + string.Join(", ", addedMods) + "."));
    if (removedMods.Count > 0) ScriptConsole.WriteLine((object)("Removed the uninstalled Workshop mods from the world " + Path.GetFileName(world) + ": " + string.Join(", ", removedMods) + "."));
}
if (File.Exists(removedList) && removedListSafe) File.Delete(removedList);

// A path the server wrote, as this host sees it: under Wine the server writes Windows paths (Z:\usr\... = /usr/...).
string LocalPath(string path)
{
    if (System.OperatingSystem.IsWindows()) return path;
    if (path.StartsWith("Z:", StringComparison.OrdinalIgnoreCase)) path = path.Substring(2);
    return path.Replace('\\', '/');
}

// The script runs as the monitor (root on Linux). A path the customer controls (LastSession.sbl, LoadWorld, a symbolic
// link a Torch plugin made) must stay in the service folder: inside `within`, with no symbolic link below the root.
bool Safe(string path, string within)
{
    var cmp = System.OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
    var top = Path.GetFullPath(root).TrimEnd('\\', '/');
    var inside = Path.GetFullPath(within).TrimEnd('\\', '/');
    var full = Path.GetFullPath(path).TrimEnd('\\', '/');
    bool Under(string p, string dir) => p.Equals(dir, cmp) || p.StartsWith(dir + Path.DirectorySeparatorChar, cmp);
    if (!Under(inside, top) || !Under(full, inside)) return false;
    for (var p = full; p != null && p.Length > top.Length; p = Path.GetDirectoryName(p))
        if (new FileInfo(p).LinkTarget != null) return false;
    return true;
}

// UTF-8 without a byte order mark, the way the server writes its files.
void Save(XDocument document, string path)
{
    var writerSettings = new XmlWriterSettings { Encoding = new UTF8Encoding(false), Indent = true };
    using (var writer = XmlWriter.Create(path, writerSettings)) document.Save(writer);
}

//refAssemblies: System.Net.Http.dll, System.IO.Compression.dll, System.IO.Compression.ZipFile.dll, System.Diagnostics.Process.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Graceful stop: on Ctrl+C the server ends the session, saves the world ("Autosave in unload", AutoRestartSave) and
// shuts down Steam. It then waits for a key press in its console window before the process exits, so this script
// ends the process itself once the shutdown is complete. On Windows windows-kill delivers the Ctrl+C event straight to
// the server process (it has a console of its own); under Wine a SIGINT does. Only the server of THIS service is
// signalled.
// The plain dedicated server or Torch (the "Torch" game update), whichever this service runs.
var binaries = new[] { "SpaceEngineersDedicated", "Torch.Server" };
const int maxWaitSeconds = 170;

var rootPath = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('\\', '/');
var root = rootPath + Path.DirectorySeparatorChar;
var instance = Path.Combine(rootPath, "Instance");

List<Process> ServerProcesses()
{
    var list = new List<Process>();
    if (System.OperatingSystem.IsWindows())
    {
        foreach (var p in binaries.SelectMany(Process.GetProcessesByName))
        {
            try { if (p.MainModule.FileName.StartsWith(root, StringComparison.OrdinalIgnoreCase)) list.Add(p); }
            catch { } // exited meanwhile
        }
        return list;
    }
    // Wine: the server's process shows Z:\<root>\DedicatedServer64\SpaceEngineersDedicated.exe in its command line.
    var rootSlash = rootPath.Replace('\\', '/') + "/";
    foreach (var dir in Directory.EnumerateDirectories("/proc"))
    {
        if (!int.TryParse(Path.GetFileName(dir), out var pid)) continue;
        try
        {
            var args = File.ReadAllText(Path.Combine(dir, "cmdline")).Replace('\0', ' ').Replace('\\', '/');
            if (binaries.Any(b => args.Contains(b + ".exe", StringComparison.OrdinalIgnoreCase)) && args.Contains(rootSlash, StringComparison.Ordinal)
                && !args.Contains("start.exe", StringComparison.OrdinalIgnoreCase))
                list.Add(Process.GetProcessById(pid));
        }
        catch { } // gone meanwhile
    }
    return list.OrderBy(p => p.Id).Take(1).ToList();
}

// The logs this run writes, and how far each was written before the stop: Instance/SpaceEngineersDedicated*.log (the
// plain server; under Torch the copy its NLog-user.config writes) and Torch's own Logs/Keen-*.log and Logs/Torch-*.log.
Dictionary<string, long> LogOffsets()
{
    var offsets = new Dictionary<string, long>();
    foreach (var (dir, pattern) in new[] { (instance, "SpaceEngineersDedicated*.log"), (Path.Combine(rootPath, "Logs"), "Keen-*.log"), (Path.Combine(rootPath, "Logs"), "Torch-*.log") })
    {
        if (!Directory.Exists(dir)) continue;
        var newest = new DirectoryInfo(dir).GetFiles(pattern).OrderBy(f => f.LastWriteTimeUtc).LastOrDefault();
        if (newest != null) offsets[newest.FullName] = newest.Length;
    }
    return offsets;
}
string ReadFrom(string path, long offset)
{
    try
    {
        using (var stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
        {
            if (stream.Length <= offset) return "";
            stream.Position = offset;
            using (var reader = new StreamReader(stream)) return reader.ReadToEnd();
        }
    }
    catch { return ""; }
}

var targets = ServerProcesses();
if (targets.Count == 0)
{
    ScriptConsole.WriteLine((object)"The server is not running.");
    return;
}
var logs = LogOffsets();

if (System.OperatingSystem.IsWindows())
{
    // windows-kill is kept in the hidden .tca folder of the service and downloaded once.
    var toolDir = Path.Combine(rootPath, ".tca");
    var killExe = Path.Combine(toolDir, "windows-kill.exe");
    if (!File.Exists(killExe))
    {
        const string url = "https://github.com/ElyDotDev/windows-kill/releases/download/1.1.4/windows-kill_1.1.4_release.zip";
        const string entryPath = "windows-kill_x64_1.1.4_lib_release/windows-kill.exe";
        try
        {
            Directory.CreateDirectory(toolDir);
            using (var http = new HttpClient())
            using (var zip = new ZipArchive(new MemoryStream(await http.GetByteArrayAsync(url, ThisCancellationToken))))
            {
                var entry = zip.GetEntry(entryPath);
                if (entry == null) throw new Exception("'" + entryPath + "' is not in the archive.");
                entry.ExtractToFile(killExe, true);
            }
        }
        catch (Exception ex)
        {
            ScriptConsole.WriteLine((object)("Could not download windows-kill (" + ex.Message + "); the panel stops the server without saving. The last autosave is kept."));
            return;
        }
    }
    foreach (var target in targets)
    {
        // CreateNoWindow gives windows-kill a console of its own, so the event never reaches the monitor.
        var psi = new ProcessStartInfo(killExe, new[] { "-SIGINT", target.Id.ToString() })
        {
            UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true, WorkingDirectory = toolDir
        };
        using (var killer = Process.Start(psi))
        {
            var output = (await killer.StandardOutput.ReadToEndAsync()).Trim();
            await killer.WaitForExitAsync(ThisCancellationToken);
            if (killer.ExitCode != 0) ScriptConsole.WriteLine((object)("windows-kill: " + output));
        }
    }
}
else
{
    // Wine turns SIGINT into the console Ctrl+C event of the Windows process.
    using (var kill = Process.Start(new ProcessStartInfo("kill", new[] { "-INT", targets[0].Id.ToString() }) { UseShellExecute = false }))
        kill.WaitForExit();
}
ScriptConsole.WriteLine((object)("Asked the server (" + string.Join(", ", targets.Select(t => t.Id)) + ") to save the world and shut down."));

for (var second = 1; second <= maxWaitSeconds; second++)
{
    await Task.Delay(1000, ThisCancellationToken);
    if (targets.All(t => { try { return t.HasExited; } catch { return true; } }))
    {
        ScriptConsole.WriteLine((object)("The server exited after " + second + " s."));
        return;
    }
    var written = string.Concat(logs.Select(l => ReadFrom(l.Key, l.Value)));
    // The plain server closes Steam last; Torch ends with "Unloaded torch session" and keeps its process alive.
    if (written.Contains("Steam closed") || written.Contains("Log Closed") || written.Contains("Unloaded torch session"))
    {
        var saved = written.Contains("Session snapshot save - END");
        ScriptConsole.WriteLine((object)((saved ? "The world was saved; the server shut down after " : "The server shut down after ") + second + " s."));
        // It now waits for a key press in its console; end it.
        foreach (var target in targets) { try { if (!target.HasExited) target.Kill(); } catch { } }
        return;
    }
}
ScriptConsole.WriteLine((object)("The server did not shut down within " + maxWaitSeconds + " s; the panel stops it now."));

