string CurrentWorld(string instanceDir)
{
    string saves = Path.Combine(instanceDir, "Saves");
    string lastSession = Path.Combine(saves, "LastSession.sbl");
    var candidates = new List<string>();
    if (File.Exists(lastSession))
    {
        var path = XDocument.Load(lastSession).Root.Elements().FirstOrDefault(e => e.Name.LocalName == "Path")?.Value ?? "";
        if (path.Length > 0)
        {
            var local = LocalPath(path);
            candidates.Add(Path.IsPathRooted(local) ? local : Path.Combine(saves, local));
            candidates.Add(Path.Combine(saves, path.TrimEnd('\\', '/').Split('\\', '/').Last()));
        }
    }
    string cfgPath = Path.Combine(instanceDir, "SpaceEngineers-Dedicated.cfg");
    if (File.Exists(cfgPath))
    {
        var loadWorld = XDocument.Load(cfgPath).Root.Elements().FirstOrDefault(e => e.Name.LocalName == "LoadWorld")?.Value ?? "";
        var localWorld = LocalPath(loadWorld);
        if (loadWorld.Length > 0) candidates.Add(Path.IsPathRooted(localWorld) ? localWorld : Path.Combine(saves, localWorld));
    }
    // Only a world folder of this service (the recorded path can be another service's folder after a copy).
    return candidates.FirstOrDefault(c => File.Exists(Path.Combine(c, "Sandbox_config.sbc")) && Safe(Path.Combine(c, "Sandbox_config.sbc"), saves));
}

// A path the server wrote, as this host sees it: under Wine the server writes Windows paths (Z:\usr\... = /usr/...).
string LocalPath(string path)
{
    if (System.OperatingSystem.IsWindows()) return path;
    if (path.StartsWith("Z:", StringComparison.OrdinalIgnoreCase)) path = path.Substring(2);
    return path.Replace('\\', '/');
}

// The script runs as the monitor (root on Linux): a file it creates belongs to the service user (root-owned files are
// hidden in the file manager).
void GiveToServiceUser(string path)
{
    if (System.OperatingSystem.IsLinux()) Globals.OperatingSystem.SetFileOwnerAutoDetect(path);
}

// The script runs as the monitor (root on Linux). A path the customer controls (LastSession.sbl, LoadWorld, a symbolic
// link a Torch plugin made) must stay in the service folder: inside `within`, with no symbolic link below the root.
bool Safe(string path, string within)
{
    var cmp = System.OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
    var top = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('\\', '/');
    var inside = Path.GetFullPath(within).TrimEnd('\\', '/');
    var full = Path.GetFullPath(path).TrimEnd('\\', '/');
    bool Under(string p, string dir) => p.Equals(dir, cmp) || p.StartsWith(dir + Path.DirectorySeparatorChar, cmp);
    if (!Under(inside, top) || !Under(full, inside)) return false;
    for (var p = full; p != null && p.Length > top.Length; p = Path.GetDirectoryName(p))
        if (new FileInfo(p).LinkTarget != null) return false;
    return true;
}

