// service root, with the same Instance folder. The "Torch" game update downloads it; the "Vanilla" update switches back.
//   update   - after the Torch update: set Torch up and start the service with Torch.Server.exe.
//   maintain - after a reinstall or a Steam update: a service that runs Torch gets the latest Torch again (a
//              reinstall deletes it; a game update usually needs a new Torch build).
//   vanilla  - after the Vanilla update: start the service with the plain dedicated server again.
const string mode = "update";
const string torchUrl = "https://build.torchapi.com/job/Torch/job/master/lastSuccessfulBuild/artifact/bin/torch-server.zip";

var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('\\', '/');
var torchExe = Path.Combine(root, "Torch.Server.exe");
var current = Convert.ToString(ThisService.Executable) ?? "";
var sep = current.Contains('/') || System.OperatingSystem.IsLinux() ? "/" : "\\";
