// link a Torch plugin made) must stay in the service folder: inside `within`, with no symbolic link below the root.
bool Safe(string path, string within)
{
    var cmp = System.OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
    var top = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('\\', '/');
    var inside = Path.GetFullPath(within).TrimEnd('\\', '/');
    var full = Path.GetFullPath(path).TrimEnd('\\', '/');
    bool Under(string p, string dir) => p.Equals(dir, cmp) || p.StartsWith(dir + Path.DirectorySeparatorChar, cmp);
    if (!Under(inside, top) || !Under(full, inside)) return false;
