//   update   - after the Torch update: set Torch up and start the service with Torch.Server.exe.
//   maintain - after a reinstall or a Steam update: a service that runs Torch gets the latest Torch again (a
//              reinstall deletes it; a game update usually needs a new Torch build).
//   vanilla  - after the Vanilla update: start the service with the plain dedicated server again.
const string mode = "vanilla";
const string torchUrl = "https://build.torchapi.com/job/Torch/job/master/lastSuccessfulBuild/artifact/bin/torch-server.zip";

var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('\\', '/');
var torchExe = Path.Combine(root, "Torch.Server.exe");
var current = Convert.ToString(ThisService.Executable) ?? "";
var sep = current.Contains('/') || System.OperatingSystem.IsLinux() ? "/" : "\\";
var vanillaExe = "DedicatedServer64" + sep + "SpaceEngineersDedicated.exe";

if (mode == "maintain")
{
    if (!current.EndsWith("Torch.Server.exe", StringComparison.OrdinalIgnoreCase)) return; // runs the plain server
    ScriptConsole.WriteLine((object)"The service runs Torch: downloading the latest Torch build.");
    var zip = Path.Combine(root, ".tca", "torch-server.zip");
    Directory.CreateDirectory(Path.GetDirectoryName(zip));
    using (var http = new HttpClient { Timeout = TimeSpan.FromMinutes(10) })
        File.WriteAllBytes(zip, await http.GetByteArrayAsync(torchUrl, ThisCancellationToken));
    // The extraction runs as root: no file of the archive may land on (or under) a symbolic link of the service folder.
    using (var archive = ZipFile.OpenRead(zip))
        foreach (var entry in archive.Entries)
            if (!Safe(Path.Combine(root, entry.FullName), root)) throw new Exception("Torch was not updated: " + entry.FullName + " in the service folder is a symbolic link.");
    ZipFile.ExtractToDirectory(zip, root, true);
    File.Delete(zip);
}

if (mode == "vanilla")
