// Wine: the plain server runs on Wine Mono, Torch does not (it loads the game from DedicatedServer64 through an
// AppDomain probing path Mono ignores). Torch needs Microsoft .NET Framework 4.8 in the service's Wine prefix: a one-time
// install of 10-20 minutes. The plain server then runs on it too.
if (System.OperatingSystem.IsLinux())
{
    var prefix = Path.Combine(root, ".wine");
    var tricksLog = Path.Combine(prefix, "winetricks.log");
    if (!File.Exists(tricksLog) || !File.ReadAllLines(tricksLog).Any(l => l.Trim() == "dotnet48"))
    {
        var user = ServiceManagerService.GetServiceCredential(ThisService.ServiceId)?.UserName;
        if (string.IsNullOrEmpty(user)) throw new Exception("The service user is unknown; cannot prepare the Wine prefix for Torch.");
        ScriptConsole.WriteLine((object)"Installing Microsoft .NET Framework 4.8 into the Wine prefix for Torch (10-20 minutes, once).");
        var display = Run("command -v xvfb-run", out _) ? "xvfb-run -a " : "";
        var installed = Run("runuser -u '" + user + "' -- env WINEPREFIX='" + prefix + "' HOME='" + root + "' WINEARCH=win64 WINEDEBUG=-all WINEDLLOVERRIDES='mscoree=;mshtml=' "
                 + display + "winetricks -q dotnet48", out var output);
        // End the prefix's processes the install left running (the server is stopped during an update).
        Run("runuser -u '" + user + "' -- env WINEPREFIX='" + prefix + "' wineserver -k", out _);
        if (!installed) throw new Exception(".NET Framework 4.8 did not install: " + string.Join("\n", output.Split('\n').TakeLast(15)));
        ScriptConsole.WriteLine((object)".NET Framework 4.8 installed.");
    }
}

