        "  <Plugins />", "  <LocalPlugins>false</LocalPlugins>", "  <DisconnectOnRestart>false</DisconnectOnRestart>",
        "  <ChatName>Server</ChatName>", "  <ChatColor>Red</ChatColor>", "  <EnableWhitelist>false</EnableWhitelist>", "  <Whitelist />",
        "  <IndependentConsole>false</IndependentConsole>", "  <EnableAnalytics>false</EnableAnalytics>", "</TorchConfig>", ""
    }));
